using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorTimelineOperations
{
    public void insert(RefCounted owner,Resource actor,Resource clip,int index,string selection){Actors(owner).Insert(index,actor);Clips(owner).Insert(index,clip);set_single_selection(owner,selection);owner.Set("selected_layer",clip.Get("layer"));Changed(owner);}
    public void remove(RefCounted owner,string id,string selection){int index=index_of(owner,id);if(index>=0){Actors(owner).RemoveAt(index);Clips(owner).RemoveAt(index);}var selected=Selected(owner);selected.Remove(id);if(index_of(owner,selection)>=0)set_single_selection(owner,selection);else owner.Set("selected_id",selected.Count>0?selected[selected.Count-1]:Variant.From(""));Changed(owner);}
    private void RemoveIndices(RefCounted owner,GArray ids){var indices=new SortedSet<int>(Comparer<int>.Create((a,b)=>b.CompareTo(a)));foreach(var value in ids){int index=index_of(owner,value.AsString());if(index>=0)indices.Add(index);}foreach(int index in indices){Actors(owner).RemoveAt(index);Clips(owner).RemoveAt(index);}}
    private void RestoreSelection(RefCounted owner,GArray ids){var copy=ids.Duplicate();var selected=Selected(owner);selected.Clear();foreach(var id in copy)if(index_of(owner,id.AsString())>=0)selected.Add(id);owner.Set("selected_id",selected.Count>0?selected[selected.Count-1]:Variant.From(""));}
    public void remove_many(RefCounted owner,GArray ids,Settings childStates){foreach(var entry in childStates){var child=actor_for_id(owner,entry.Key.AsString());if(child==null)continue;var state=entry.Value.AsGodotDictionary();apply_parent_state_silent(child,state["new_parent"].AsString(),state["new_values"].AsGodotDictionary());}RemoveIndices(owner,ids);Selected(owner).Clear();owner.Set("selected_id","");Changed(owner);}
    public void insert_many(RefCounted owner,GArray removed,GArray selection,Settings childStates)
    {
        var ordered=new List<Settings>();foreach(var value in removed)ordered.Add(value.AsGodotDictionary());ordered.Sort((a,b)=>a["index"].AsInt32().CompareTo(b["index"].AsInt32()));foreach(var entry in ordered){Actors(owner).Insert(entry["index"].AsInt32(),entry["actor"]);Clips(owner).Insert(entry["index"].AsInt32(),entry["clip"]);}foreach(var entry in childStates){var child=actor_for_id(owner,entry.Key.AsString());if(child==null)continue;var state=entry.Value.AsGodotDictionary();apply_parent_state_silent(child,state["old_parent"].AsString(),state["old_values"].AsGodotDictionary());}RestoreSelection(owner,selection);Changed(owner);
    }
    public void insert_copies(RefCounted owner,GArray entries,GArray selection){foreach(var value in entries){var entry=value.AsGodotDictionary();Actors(owner).Add(entry["actor"]);Clips(owner).Add(entry["clip"]);}RestoreSelection(owner,selection);var clip=selected_clip(owner);if(clip!=null)owner.Set("selected_layer",clip.Get("layer"));Changed(owner);}
    public void remove_copies(RefCounted owner,GArray ids,GArray previous){RemoveIndices(owner,ids);RestoreSelection(owner,previous);Changed(owner);}
    public void remove_with_child_states(RefCounted owner,string id,string selection,Settings childStates,bool useNew){foreach(var entry in childStates){var child=actor_for_id(owner,entry.Key.AsString());if(child==null)continue;var state=entry.Value.AsGodotDictionary();set_parent_state(owner,child,state[useNew?"new_parent":"old_parent"].AsString(),state[useNew?"new_values":"old_values"].AsGodotDictionary());}remove(owner,id,selection);}
    public void insert_with_child_states(RefCounted owner,Resource actor,Resource clip,int index,string selection,Settings childStates){insert(owner,actor,clip,index,selection);foreach(var entry in childStates){var child=actor_for_id(owner,entry.Key.AsString());if(child==null)continue;var state=entry.Value.AsGodotDictionary();set_parent_state(owner,child,state["old_parent"].AsString(),state["old_values"].AsGodotDictionary());}}
    public void set_start(RefCounted owner,Resource clip,double time,int layer){clip.Set("start_time",time);clip.Set("layer",layer);clip.EmitChanged();make_primary(owner,clip.Get("id").AsString());owner.Set("selected_layer",layer);Changed(owner);}
    public void move_clip(RefCounted owner,string id,double time,int layer)
    {
        int index=index_of(owner,id);if(index<0||!double.IsFinite(time))return;var clip=Clips(owner)[index].As<Resource>();var linked=linked_clip_ids(owner,new GArray{id});if(linked.Count>1){int layerDelta=layer<0?0:layer-clip.Get("layer").AsInt32();double delta=nearest_free_group_delta(owner,Variant.From(linked).AsGodotArray(),time-clip.Get("start_time").AsDouble(),layerDelta);var states=new Settings();foreach(string childId in linked){var child=Clips(owner)[index_of(owner,childId)].As<Resource>();states[childId]=new Settings{["start"]=child.Get("start_time").AsDouble()+delta,["duration"]=child.Get("duration"),["offset"]=child.Get("source_offset"),["layer"]=child.Get("layer").AsInt32()+layerDelta};}commit_clip_states(owner,states,"Move Linked Actors",id);return;}double target=Math.Max(time,0);int targetLayer=layer<0?clip.Get("layer").AsInt32():layer;target=nearest_free_start(owner,id,target,clip.Get("duration").AsDouble(),targetLayer);if(!can_place(owner,id,target,clip.Get("duration").AsDouble(),targetLayer)||Mathf.IsEqualApprox(target,clip.Get("start_time").AsDouble())&&targetLayer==clip.Get("layer").AsInt32())return;History(owner,"Move Actor","_set_start",new GArray{clip,target,targetLayer},"_set_start",new GArray{clip,clip.Get("start_time"),clip.Get("layer")});Changed(owner);
    }
    public Resource? split_clip(RefCounted owner,string id,double time)
    {
        int index=index_of(owner,id);if(index<0)return null;var left=Clips(owner)[index].As<Resource>();double length=time-left.Get("start_time").AsDouble();if(length<.1||left.Get("duration").AsDouble()-length<.1)return null;var original=Actors(owner)[index].As<Resource>();var actor=_data.copy_actor(original);actor.Set("id",_data.new_id());var right=_runtime.create_clip(actor,time,left.Get("duration").AsDouble()-length);right.Set("layer",left.Get("layer"));right.Set("playback_speed",left.Get("playback_speed"));right.Set("source_offset",left.Get("source_offset").AsDouble()+length*left.Get("playback_speed").AsDouble());string focus=owner.Get("focused_actor_id").AsString(),nextFocus=focus==left.Get("actor_id").AsString()?original.Get("parent_id").AsString():focus;History(owner,"Split Actor","_apply_split",new GArray{left,length,actor,right,nextFocus},"_undo_split",new GArray{left,left.Get("duration"),right.Get("id"),Selected(owner).Duplicate(),focus});return right;
    }
    public void apply_split(RefCounted owner,Resource left,double length,Resource actor,Resource right,string focus){left.Set("duration",length);owner.Set("focused_actor_id",focus);left.EmitChanged();insert_copies(owner,new GArray{new Settings{["actor"]=actor,["clip"]=right}},new GArray{right.Get("id")});}
    public void undo_split(RefCounted owner,Resource left,double duration,string rightId,GArray selection,string focus){left.Set("duration",duration);owner.Set("focused_actor_id",focus);left.EmitChanged();remove_copies(owner,new GArray{rightId},selection);}
}
